(()=>{'use strict';const entry=document.getElementById('start');if(entry&&window.IntersectionObserver)new window.IntersectionObserver(items=>document.body.classList.toggle('mw-at-entry',items[0].isIntersecting)).observe(entry);function revealHash(){const target=document.getElementById(location.hash.slice(1));if(target){let el=target.parentElement;while(el){if(el.tagName==='DETAILS')el.open=true;el=el.parentElement;}}}window.addEventListener('hashchange',revealHash);revealHash();document.querySelector('.mw-film')?.addEventListener('toggle',function(){this.querySelector('summary i').textContent=this.open?'CLOSE THE FILM −':'OPEN THE FILM +';window.dispatchEvent(new Event('resize'));});const artRoot=document.getElementById('mw-art-grid');if(!artRoot)return;const rows=window.CAISIK_ART||[];const category=document.getElementById('mw-category'),search=document.getElementById('mw-search'),count=document.getElementById('mw-count'),empty=document.getElementById('mw-empty'),dialog=document.getElementById('mw-art-modal'),preview=document.getElementById('mw-preview'),title=document.getElementById('mw-modal-title'),download=document.getElementById('mw-download');let selected,trigger;
function render(){const q=search.value.trim().toLowerCase(),cat=category.value;let visible=0;for(const card of artRoot.querySelectorAll('.mw-art-card')){const row=rows.find(r=>r.slug===card.dataset.slug);const show=(!cat||row.category===cat)&&(!q||(row.title+' '+row.category+' '+(row.description||'')).toLowerCase().includes(q));card.hidden=!show;if(show)visible++;}count.textContent=visible+' / '+rows.length+' ARTWORKS';empty.hidden=visible>0;}
category.addEventListener('change',render);search.addEventListener('input',render);const requested=new URLSearchParams(location.search).get('category');if(rows.some(r=>r.category===requested))category.value=requested;
artRoot.addEventListener('click',e=>{const button=e.target.closest('[data-art]');if(!button)return;selected=rows.find(r=>r.slug===button.dataset.art);if(!selected)return;trigger=button;const png=document.getElementById('mw-png');png.removeAttribute('href');png.setAttribute('aria-disabled','true');png.textContent='PREPARING PNG…';preview.src=selected.image;preview.alt=selected.title+" — "+selected.description;title.textContent=selected.title;document.getElementById('mw-practice').textContent=selected.practice;document.getElementById('mw-format-note').textContent=selected.alpha?'Transparent cutout. Choose a backdrop to preview its edges.':'Composed on a dark background.';download.href=selected.image;download.download='caisik-'+selected.slug+'.webp';document.getElementById('mw-transparency').dataset.backdrop='dark';document.getElementById('mw-transparency').style.backgroundColor='';document.getElementById('mw-transparency').style.backgroundImage='';dialog.showModal();});
document.getElementById('mw-modal-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>trigger?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
for(const button of document.querySelectorAll('[data-backdrop]'))button.onclick=()=>{const back=document.getElementById('mw-transparency');back.dataset.backdrop=button.dataset.backdrop;back.style.backgroundImage='';back.style.backgroundColor=button.dataset.backdrop==='dark'?'#101012':button.dataset.backdrop==='light'?'#eee':'';};render();})();
(()=>{const link=document.getElementById('mw-png'),preview=document.getElementById('mw-preview');if(!link||!preview)return;let url;preview.addEventListener('load',async()=>{const requested=preview.src;try{const canvas=document.createElement('canvas');canvas.width=preview.naturalWidth;canvas.height=preview.naturalHeight;const context=canvas.getContext('2d');if(!context)throw new Error('Canvas unavailable');context.drawImage(preview,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('PNG unavailable');if(preview.src!==requested)return;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);link.href=url;link.download='caisik-'+requested.split('/').pop().replace('.webp','.png');link.setAttribute('aria-disabled','false');link.textContent='DOWNLOAD PNG ↓';}catch(error){link.textContent='PNG UNAVAILABLE — USE WEBP';link.setAttribute('aria-disabled','true');}});})();
